package org.transittr.tests;
import android.app.Instrumentation;import android.os.Bundle;import java.lang.reflect.*;import java.util.*;import org.json.*;
public final class ApproachCheck extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}private void check(boolean ok,String m){if(!ok)throw new AssertionError(m);}
 public void onStart(){Bundle out=new Bundle();boolean pass=false;try{ClassLoader l=getTargetContext().getClassLoader();Class<?> recent=l.loadClass("org.transittr.RecentQueries");Method update=recent.getMethod("update",String.class,Integer.TYPE,String.class,String.class,String.class);String old="[]";for(int i=0;i<9;i++)old=update.invoke(null,old,Integer.valueOf(0),String.valueOf(10000+i),"481","").toString();JSONArray a=new JSONArray(old);check(a.length()==8,"history bounded to eight");old=update.invoke(null,old,Integer.valueOf(0),"10005","481","").toString();a=new JSONArray(old);check(a.length()==8&&"10005".equals(a.getJSONObject(0).getString("stop")),"history dedupe and order");int count=0;for(int i=0;i<a.length();i++)if("10005".equals(a.getJSONObject(i).getString("stop")))count++;check(count==1,"one history entry");
 Class<?> snap=l.loadClass("org.transittr.JourneyData$Snapshot"),veh=l.loadClass("org.transittr.JourneyData$Vehicle"),entry=l.loadClass("org.transittr.WidgetFavorites$Entry"),alert=l.loadClass("org.transittr.ApproachAlert");Object snapshot=snap.newInstance(),wanted=entry.newInstance();entry.getField("city").setInt(wanted,0);entry.getField("line").set(wanted,"481");entry.getField("direction").set(wanted,"");ArrayList rows=(ArrayList)snap.getField("rows").get(snapshot);Object valid=veh.newInstance();veh.getField("line").set(valid,"481");veh.getField("etaSeconds").setLong(valid,300);rows.add(valid);Object stale=veh.newInstance();veh.getField("line").set(stale,"481");veh.getField("etaSeconds").setLong(stale,30);veh.getField("signalAgeSeconds").setInt(stale,181);rows.add(stale);Object wrong=veh.newInstance();veh.getField("line").set(wrong,"999");veh.getField("etaSeconds").setLong(wrong,10);rows.add(wrong);Object nodata=veh.newInstance();veh.getField("line").set(nodata,"481");veh.getField("eta").set(nodata,"2 durak");rows.add(nodata);Method nearest=alert.getMethod("nearest",snap,entry);check(((Long)nearest.invoke(null,snapshot,wanted)).longValue()==300,"ignores stale or non-minute values");veh.getField("passed").setBoolean(valid,true);check(((Long)nearest.invoke(null,snapshot,wanted)).longValue()==Long.MAX_VALUE,"no fabricated minutes or passed buses");pass=true;out.putString("stream","PASS Android "+android.os.Build.VERSION.RELEASE+"; recent history bounded/deduplicated; alerts exclude stale, passed and non-minute data\n");}catch(Throwable e){java.io.StringWriter w=new java.io.StringWriter();e.printStackTrace(new java.io.PrintWriter(w));out.putString("stream","FAIL "+w);}finish(pass?-1:0,out);}
}
